### ✅ Complete Binary Search Program (Iterative + Recursive)

```c
#include <stdio.h>

int binarySearchIter(int arr[], int n, int key) {
    int low = 0, high = n - 1;

    while (low <= high) {
        int mid = (low + high) / 2;

        if (arr[mid] == key)
            return mid;
        else if (arr[mid] < key)
            low = mid + 1;
        else
            high = mid - 1;
    }
    return -1;
}

int binarySearchRec(int arr[], int low, int high, int key) {
    if (low > high)
        return -1;

    int mid = (low + high) / 2;

    if (arr[mid] == key)
        return mid;
    else if (arr[mid] < key)
        return binarySearchRec(arr, mid + 1, high, key);
    else
        return binarySearchRec(arr, low, mid - 1, key);
}

int main() {
    int arr[50], n, key, pos;

    printf("Enter number of elements: ");
    scanf("%d", &n);

    printf("Enter %d sorted elements:\n", n);
    for (int i = 0; i < n; i++)
        scanf("%d", &arr[i]);

    printf("Enter element to search: ");
    scanf("%d", &key);

    // Iterative Search
    pos = binarySearchIter(arr, n, key);
    if (pos != -1)
        printf("Iterative: Found at index %d\n", pos);
    else
        printf("Iterative: Not found\n");

    // Recursive Search
    pos = binarySearchRec(arr, 0, n - 1, key);
    if (pos != -1)
        printf("Recursive: Found at index %d\n", pos);
    else
        printf("Recursive: Not found\n");

    return 0;
}
```

